(function(root){const core=root.FNDynamic||(typeof require==='function'?require('./dynamic-core.js'):null);
function run(example){const start=Date.parse(example.anchor),at=m=>start+m*60000;let d=core.initialize({patientId:'SIM-'+example.enteredId,label:example.name,input:example.input,triageAt:example.anchor,mode:'simulation'},start),seq=0;const actions=[],expectations=[];
 const queue=(minute,role,operation)=>actions.push({minute,role,operation});
 queue(1,'physician',{action:'request_test',testId:'culture-main',name:'Blood / source culture',ownerLabel:'Simulation physician',note:'Scripted requested specimen'});queue(5,'nurse',{action:'test_status',testId:'culture-main',status:'collected',actualAt:new Date(at(5)).toISOString(),note:'Invented teaching collection time'});queue(10,'nurse',{action:'test_status',testId:'culture-main',status:'received',actualAt:new Date(at(10)).toISOString(),note:'Invented teaching specimen receipt'});
 for(const [i,code]of ['review','labs','cultures'].entries()){const task=d.tasks.find(t=>t.code===code);if(!task)continue;queue(2+i,'physician',{action:'approve_task',taskId:task.id,note:'Scripted clinical approval'});queue(6+i,task.ownerRole,{action:'complete_task',taskId:task.id,actualAt:new Date(at(6+i)).toISOString(),note:'Invented documented teaching action; not real care'});}
 queue(11,'physician',{action:'propose_plan',plan:'Fictional baseline clinician plan; verify all reference doses and local policy',note:'Teaching plan proposal'});queue(12,'pharmacist',{action:'pharmacy_plan',decision:'approve',note:'Scripted pharmacy review'});
 if(!example.input.priorAntibiotic)queue(20,'nurse',{action:'record_dose',actualAt:new Date(at(20)).toISOString(),regimen:core.summarize(example.input).meds.map(m=>m.name+' / '+m.first).join('; ')||'Individualized teaching regimen after specialist selection',note:'Invented infusion-start documentation; no actual prescription or administration'});
 example.events.forEach((event,index)=>{queue(event.at+2/60,'nurse',{action:'observe',event:{patch:event.patch,result:event.result||undefined,observedAt:new Date(at(event.at)).toISOString(),availableAt:new Date(at(event.at)).toISOString(),source:'Scripted fictional example '+example.id},check:index});queue(event.at+example.reviewDelayMinutes+2/60,'physician',{_followup:true,index,event});});
 actions.sort((a,b)=>a.minute-b.minute);
 for(const item of actions){const actor={id:'SIM-'+item.role,role:item.role};if(item.operation._followup){const a=d.alerts.filter(a=>!a.review).at(-1);if(!a)continue;const perform=(op,offset=0)=>{d=core.mutate(d,{...op,operationKey:example.id+'-script-'+(++seq)},actor,at(item.minute+offset))};perform({action:'review_alert',alertId:a.id,note:'Scripted physician reviewed changed data'});const test=d.tests.find(t=>t.latest?.alertId===a.id);if(test){perform({action:'ack_result',testId:test.id,reportId:test.latest.id,note:'Scripted current report review'});if(test.latest.code==='culture')perform({action:'culture_decision',testId:test.id,reportId:test.latest.id,decision:'escalate',note:'Scripted clinician decision: ID/pharmacy to reconcile organism, AST and treatment'},1)}else perform({action:'decide_alert',alertId:a.id,decision:'revise',note:'Scripted reassessment decision; no automatic treatment change'},1);const task=d.tasks.filter(t=>t.code==='change_review'&&t.status==='proposed').at(-1);if(task){perform({action:'approve_task',taskId:task.id,note:'Scripted reassessment task approval'},1);perform({action:'complete_task',taskId:task.id,actualAt:new Date(at(item.minute+1)).toISOString(),note:'Invented teaching review completion'},1)}perform({action:'propose_plan',plan:'Revised fictional plan for current findings: '+d.current.risk+'. Reference medicines require case-specific approval.',note:'Scripted updated physician plan'},2);d=core.mutate(d,{action:'pharmacy_plan',decision:'approve',note:'Scripted current-revision pharmacy review',operationKey:example.id+'-script-'+(++seq)},{id:'SIM-pharmacist',role:'pharmacist'},at(item.minute+3));
 }else{const op={...item.operation,operationKey:example.id+'-script-'+(++seq)};d=core.mutate(d,op,actor,at(item.minute));if(op.action==='observe')expectations.push({stage:op.check,expected:example.expectedAfter[op.check],actual:d.current.risk,pass:d.current.risk===example.expectedAfter[op.check]});}}
 return {exampleId:example.id,name:example.name,initialExpected:example.expectedInitial,initialActual:core.summarize(example.input).risk,checks:expectations,episode:d};}
function cohort(examples){const runs=examples.map(run),episodes=runs.map(r=>r.episode);return {kind:'scripted_simulation',generatedBy:'FNDynamic deterministic test runner',clinicalOutcomesProven:false,summary:core.metrics(episodes,'simulation',Date.parse(examples[0].anchor)+5*86400000),runs,pass:runs.every(r=>r.initialExpected===r.initialActual&&r.checks.every(c=>c.pass))}}
const api={run,cohort};root.FNDynamicValidation=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
